INSERT INTO auth.users(id,aud,role,email,email_confirmed_at) VALUES('a1580000-0000-0000-0000-000000000001','authenticated','authenticated','qa-maint-owner@example.test',now()),('a1580000-0000-0000-0000-000000000002','authenticated','authenticated','qa-maint-other@example.test',now());
INSERT INTO maint_vars SELECT 'ws',id FROM public.workspaces WHERE owner_id='a1580000-0000-0000-0000-000000000001';
INSERT INTO maint_vars SELECT 'otherws',public.fn_create_workspace(p_name=>'QA Other Owned',p_currency=>'BRL',p_tracking_mode=>'full');
INSERT INTO maint_vars SELECT 'owner',id FROM public.workspace_members WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws') AND role='owner';
INSERT INTO public.workspace_members(workspace_id,user_id,role) SELECT id,'a1580000-0000-0000-0000-000000000002','admin' FROM maint_vars WHERE name='ws';
INSERT INTO public.accounts(workspace_id,name,type,initial_balance,current_balance) SELECT id,'Unrelated','checking',55,66 FROM maint_vars WHERE name='otherws';
INSERT INTO maint_vars SELECT 'purchase',public.fn_create_purchase_with_splits(p_workspace_id=>(SELECT id FROM maint_vars WHERE name='ws'),p_description=>'600/3',p_total_amount=>600,p_installment_count=>3,p_purchase_date=>'2050-01-10',p_credit_card_id=>(SELECT id FROM maint_vars WHERE name='card'),p_paid_installments_count=>1,p_paid_by_member_id=>(SELECT id FROM maint_vars WHERE name='owner'),p_split_type=>'equal',p_splits=>jsonb_build_array(jsonb_build_object('member_id',(SELECT id FROM maint_vars WHERE name='owner'),'amount',300),jsonb_build_object('person_id',(SELECT id FROM maint_vars WHERE name='person'),'amount',300,'repaid_installments_count',1)));
INSERT INTO maint_vars SELECT 'tx',public.fn_create_transaction_with_splits(p_workspace_id=>(SELECT id FROM maint_vars WHERE name='ws'),p_description=>'Paid',p_amount=>100,p_account_id=>(SELECT id FROM maint_vars WHERE name='account'),p_status=>'paid',p_type=>'expense');
INSERT INTO public.budgets(workspace_id,category_id,month,year,planned_amount) SELECT w.id,c.id,1,2050,100 FROM maint_vars w,maint_vars c WHERE w.name='ws' AND c.name='category';
INSERT INTO public.recurring_transactions(workspace_id,description,amount,type,frequency,start_date,next_occurrence,active,auto_create) SELECT id,'Future',10,'expense','monthly','2050-01-10','2050-02-10',false,false FROM maint_vars WHERE name='ws';
INSERT INTO public.settlements(workspace_id,from_person_id,to_member_id,amount,settlement_date) SELECT w.id,p.id,m.id,5,CURRENT_DATE FROM maint_vars w,maint_vars p,maint_vars m WHERE w.name='ws' AND p.name='person' AND m.name='owner';
INSERT INTO public.financial_operations(workspace_id,operation_kind,operation_key,payload,result_id,created_by) SELECT w.id,'fn_create_purchase_with_splits','old-purchase-key',jsonb_build_object('description','Private original financial payload'),p.id,'a1580000-0000-0000-0000-000000000001' FROM maint_vars w,maint_vars p WHERE w.name='ws' AND p.name='purchase';
INSERT INTO maint_preview SELECT 'original',public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws'));
INSERT INTO maint_results SELECT is(((SELECT preview FROM maint_preview WHERE stage='original')->'counts'->>'goal_deposits')::int,1,'Preview includes actual goal deposit history');
INSERT INTO maint_results SELECT is(((SELECT preview FROM maint_preview WHERE stage='original')->'counts'->>'settlements')::int,1,'Preview includes manual settlement history');
INSERT INTO maint_results SELECT is((SELECT current_balance FROM public.accounts WHERE id=(SELECT id FROM maint_vars WHERE name='account')),825::numeric,'Fixture has real payment, transfer and goal debits');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear','wrong',(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'wrong-name')$q$,'23514',NULL,'Exact typed workspace name required');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear',(SELECT preview->>'name' FROM maint_preview WHERE stage='original'),'stale','stale')$q$,'PT409',NULL,'Stale preview rejected before deletion');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear',(SELECT preview->>'name' FROM maint_preview WHERE stage='original'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'changed-settlement')$q$,'PT409',NULL,'A newly edited settlement invalidates the destructive preview');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws'))$q$,'42501',NULL,'Admin cannot preview destructive owner action');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear',(SELECT preview->>'name' FROM maint_preview WHERE stage='original'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'admin')$q$,'42501',NULL,'Admin cannot clear workspace');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'delete','any','any','viewer')$q$,'42501',NULL,'Viewer cannot delete workspace');
INSERT INTO maint_results SELECT throws_ok($q$DELETE FROM public.workspaces WHERE id=(SELECT id FROM maint_vars WHERE name='ws')$q$,'42501',NULL,'Owner also cannot bypass the maintenance RPC with direct DELETE');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear',(SELECT preview->>'name' FROM maint_preview WHERE stage='original'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'rollback')$q$,'P0001','QA injected failure','Late failure rolls back the complete clear operation');
INSERT INTO maint_results SELECT is(public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws'))->>'fingerprint',(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'Every source row and balance preserved after rollback');
INSERT INTO maint_results SELECT is((SELECT count(*)::int FROM public.workspace_maintenance_operations WHERE operation_key='rollback'),0,'Failed action leaves no success receipt');
INSERT INTO maint_results SELECT lives_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear',(SELECT preview->>'name' FROM maint_preview WHERE stage='original'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'clear')$q$,'Owner clears paid and repaid financial history successfully');
INSERT INTO maint_results SELECT is((SELECT sum(value::int)::int FROM jsonb_each_text(public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws'))->'counts')),0,'All transactions, bills, purchases, payments, transfers, recurrences, budgets and goals removed');
INSERT INTO maint_results SELECT is(public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws'))->'retained',(SELECT preview->'retained' FROM maint_preview WHERE stage='original'),'All catalogs, archived people and member access preserved');
INSERT INTO maint_results SELECT is((SELECT current_balance FROM public.accounts WHERE id=(SELECT id FROM maint_vars WHERE name='account')),1000::numeric,'Source balance reset to initial value');
INSERT INTO maint_results SELECT is((SELECT current_balance FROM public.accounts WHERE id=(SELECT id FROM maint_vars WHERE name='target')),100::numeric,'Transfer destination reset to initial value');
INSERT INTO maint_results SELECT ok((SELECT bool_and(payload=jsonb_build_object('cleared',true)) FROM public.financial_operations WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws')),'Old operation payloads redacted but retry tombstones retained');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_execute_financial_operation((SELECT id FROM maint_vars WHERE name='ws'),'fn_create_purchase_with_splits','old-purchase-key',jsonb_build_object('p_workspace_id',(SELECT id FROM maint_vars WHERE name='ws')))$q$,'P0001',NULL,'An old financial retry cannot recreate cleared purchases');
INSERT INTO maint_preview SELECT 'cleared',public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws'));
INSERT INTO maint_results SELECT is((public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear',(SELECT preview->>'name' FROM maint_preview WHERE stage='original'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'clear')->>'replayed')::boolean,true,'Retry of the same clear returns its original receipt');
INSERT INTO maint_results SELECT is((SELECT count(*)::int FROM public.transactions WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws')),1,'Retry preserves a transaction created after clearing');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'clear',(SELECT preview->>'name' FROM maint_preview WHERE stage='cleared'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='cleared'),'changed')$q$,'PT409',NULL,'New entries invalidate an old fresh preview');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'delete',(SELECT preview->>'name' FROM maint_preview WHERE stage='original'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='original'),'clear')$q$,'23514',NULL,'An operation key cannot be reused for deletion');
INSERT INTO maint_preview SELECT 'deletion',public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws'));
INSERT INTO maint_results SELECT lives_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'delete',(SELECT preview->>'name' FROM maint_preview WHERE stage='deletion'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='deletion'),'delete')$q$,'Owner deletes the workspace through the protected RPC');
INSERT INTO maint_results SELECT is((SELECT count(*)::int FROM public.workspaces WHERE id=(SELECT id FROM maint_vars WHERE name='ws')),0,'Workspace removed');
INSERT INTO maint_results SELECT ok(NOT EXISTS(SELECT 1 FROM public.accounts WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws')) AND NOT EXISTS(SELECT 1 FROM public.people WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws')) AND NOT EXISTS(SELECT 1 FROM public.payment_methods WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws')),'Deletion also removes retained catalogs');
INSERT INTO maint_results SELECT is((SELECT current_balance FROM public.accounts WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='otherws')),66::numeric,'Unrelated workspace balance remains unchanged');
INSERT INTO maint_results SELECT is((public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='ws'),'delete',(SELECT preview->>'name' FROM maint_preview WHERE stage='deletion'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='deletion'),'delete')->>'replayed')::boolean,true,'Delete can be retried after the workspace no longer exists');
INSERT INTO public.workspaces(name,owner_id,currency) VALUES('QA Inaccessible owned','a1580000-0000-0000-0000-000000000001','BRL');
INSERT INTO maint_preview SELECT 'last',public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='otherws'));
INSERT INTO maint_results SELECT is(((SELECT preview FROM maint_preview WHERE stage='last')->>'can_delete')::boolean,false,'An inaccessible ownership row cannot defeat the last-workspace guard');
INSERT INTO maint_results SELECT throws_ok($q$SELECT public.fn_maintain_workspace((SELECT id FROM maint_vars WHERE name='otherws'),'delete',(SELECT preview->>'name' FROM maint_preview WHERE stage='last'),(SELECT preview->>'fingerprint' FROM maint_preview WHERE stage='last'),'last')$q$,'23514',NULL,'Last workspace guard enforced in the database');
INSERT INTO maint_results SELECT throws_ok($q$SELECT * FROM public.workspace_maintenance_operations$q$,'42501',NULL,'Internal receipts cannot be read by authenticated clients');
INSERT INTO maint_results SELECT ok(NOT has_function_privilege('anon','public.fn_maintain_workspace(uuid,text,text,text,text)','EXECUTE'),'Anonymous destructive RPC denied');
INSERT INTO maint_results SELECT ok(NOT has_function_privilege('authenticated','public.fn_workspace_maintenance_snapshot(uuid)','EXECUTE'),'Internal snapshot helper is private');
INSERT INTO maint_results SELECT is((SELECT count(*)::int FROM public.workspace_maintenance_operations WHERE owner_id='a1580000-0000-0000-0000-000000000001'),2,'Only the two committed actions have durable receipts');
