BEGIN;
SELECT plan(35);
CREATE TEMP TABLE maint_results(msg text);
CREATE TEMP TABLE maint_vars(name text,id uuid);
CREATE TEMP TABLE maint_preview(stage text,preview jsonb);
SELECT set_config('request.jwt.claim.sub','a1580000-0000-0000-0000-000000000001',true);
WITH a AS(INSERT INTO public.accounts(workspace_id,name,type,initial_balance,current_balance) SELECT id,'Source','checking',1000,1000 FROM maint_vars WHERE name='ws' RETURNING id) INSERT INTO maint_vars SELECT 'account',id FROM a;
WITH a AS(INSERT INTO public.accounts(workspace_id,name,type,initial_balance,current_balance) SELECT id,'Target','checking',100,100 FROM maint_vars WHERE name='ws' RETURNING id) INSERT INTO maint_vars SELECT 'target',id FROM a;
WITH c AS(INSERT INTO public.credit_cards(workspace_id,name,credit_limit,closing_day,due_day) SELECT id,'Card',5000,20,10 FROM maint_vars WHERE name='ws' RETURNING id) INSERT INTO maint_vars SELECT 'card',id FROM c;
WITH c AS(INSERT INTO public.categories(workspace_id,name,type) SELECT id,'Category','expense' FROM maint_vars WHERE name='ws' RETURNING id) INSERT INTO maint_vars SELECT 'category',id FROM c;
WITH p AS(INSERT INTO public.payment_methods(workspace_id,name,type,active) SELECT id,'Pix','pix',true FROM maint_vars WHERE name='ws' RETURNING id) INSERT INTO maint_vars SELECT 'method',id FROM p;
WITH p AS(INSERT INTO public.people(workspace_id,name,archived) SELECT id,'Person',true FROM maint_vars WHERE name='ws' RETURNING id) INSERT INTO maint_vars SELECT 'person',id FROM p;
-- Existing historical references may be archived; create while active, then archive.
UPDATE public.people SET archived=false WHERE id=(SELECT id FROM maint_vars WHERE name='person');
SELECT public.fn_create_transfer(p_workspace_id=>(SELECT id FROM maint_vars WHERE name='ws'),p_from_account_id=>(SELECT id FROM maint_vars WHERE name='account'),p_to_account_id=>(SELECT id FROM maint_vars WHERE name='target'),p_amount=>50);
WITH g AS(INSERT INTO public.financial_goals(workspace_id,name,target_amount,current_amount,status) SELECT id,'Goal',300,0,'in_progress' FROM maint_vars WHERE name='ws' RETURNING id) INSERT INTO maint_vars SELECT 'goal',id FROM g;
SELECT public.fn_record_goal_deposit(p_workspace_id=>(SELECT id FROM maint_vars WHERE name='ws'),p_goal_id=>(SELECT id FROM maint_vars WHERE name='goal'),p_account_id=>(SELECT id FROM maint_vars WHERE name='account'),p_amount=>25,p_idempotency_key=>'qa-maint-deposit');
UPDATE public.people SET archived=true WHERE id=(SELECT id FROM maint_vars WHERE name='person');
CREATE FUNCTION pg_temp.fail_workspace_maintenance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.workspace_id=(SELECT id FROM maint_vars WHERE name='ws') THEN RAISE EXCEPTION 'QA injected failure'; END IF; RETURN OLD; END $$;
CREATE TRIGGER qa_maintenance_failure BEFORE DELETE ON public.financial_goals FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_workspace_maintenance();
GRANT ALL ON maint_vars,maint_preview,maint_results TO authenticated;
SET LOCAL role='authenticated';
RESET ROLE;
UPDATE public.settlements SET amount=6 WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws');
SET LOCAL role='authenticated';
SELECT set_config('request.jwt.claim.sub','a1580000-0000-0000-0000-000000000002',true);
RESET ROLE;
UPDATE public.workspace_members SET role='viewer' WHERE workspace_id=(SELECT id FROM maint_vars WHERE name='ws') AND user_id='a1580000-0000-0000-0000-000000000002';
SET LOCAL role='authenticated';
SELECT set_config('request.jwt.claim.sub','a1580000-0000-0000-0000-000000000001',true);
-- Role changes invalidate previews; accept a fresh one before testing atomic rollback.
UPDATE maint_preview SET preview=public.fn_preview_workspace_maintenance((SELECT id FROM maint_vars WHERE name='ws')) WHERE stage='original';
RESET ROLE;
DROP TRIGGER qa_maintenance_failure ON public.financial_goals;
SET LOCAL role='authenticated';
SELECT public.fn_create_transaction_with_splits(p_workspace_id=>(SELECT id FROM maint_vars WHERE name='ws'),p_description=>'New after clear',p_amount=>1,p_account_id=>(SELECT id FROM maint_vars WHERE name='account'),p_status=>'pending');
RESET ROLE;
SET LOCAL role='authenticated';
RESET ROLE;
SELECT (SELECT array_agg(msg) FROM maint_results WHERE msg LIKE 'not ok%') AS not_ok_messages,extensions._get('curr_test')::int AS ran,extensions._get('plan')::int AS planned,extensions.num_failed()::int AS failed,ARRAY(SELECT * FROM extensions.finish()) AS finish_diagnostics;
ROLLBACK;
